local zones = {
	[947] = {
		name = "Azeroth",
		short = "Hace diez mil años, los Altonato de Kalimdor, embriagados por el poder del Pozo de la Eternidad, respondieron al llamado del titán caído Sargeras y abrieron un portal para la Legión Ardiente.",
		full = "Hace diez mil años, los Altonato de Kalimdor, embriagados por el poder del Pozo de la Eternidad, respondieron al llamado del titán caído Sargeras y abrieron un portal para la Legión Ardiente. Malfurion Tempestira y la resistencia kaldorei destruyeron ese portal con el Alma de Dragón y arrojaron a Sargeras de vuelta al Vacío Abisal, pero el colapso del Pozo quebró el mundo entero. La antigua Kalimdor se hundió entre fuego e inundaciones; continentes en ruinas surgieron de los restos, y el corazón anegado de aquella tierra se convirtió en el Mare Magnum, con La Vorágine rugiendo donde antes se alzaba el Pozo.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Durotar es una tierra roja y agrietada de riscos y cañones, seca y calurosa, escasa en agua y en vegetación.",
		full = "Durotar es una tierra roja y agrietada de riscos y cañones, seca y calurosa, escasa en agua y en vegetación. Los orcos encuentran en ella una belleza áspera que les recuerda a Draenor, y fue aquí, después del Monte Hyjal, donde Thrall condujo a su pueblo para construir una nueva patria, a la que dio el nombre de su padre asesinado, Durotan. Esta tierra había pertenecido a los jabaespines Crines de Acero hasta que la Horda los expulsó.\n\nAquella paz no duró mucho. El almirante general Daelin Valiente, héroe de la Segunda Guerra y enemigo de los orcos, lanzó una gran flota de la Alianza contra Durotar, decidido a aplastar a la Horda antes de que pudiera echar raíces. Su hija Jaina eligió otro camino: en Theramore se volvió contra su propio padre para luchar junto a Thrall, y Daelin murió en la batalla sin que ambos pudieran reconciliarse jamás. En agradecimiento por su lealtad, Thrall permitió que los soldados de Jaina se retiraran a Theramore sin sufrir daño alguno.\n\nLos trols Lanza Negra llegaron a la costa de Durotar como exiliados, no como colonos por voluntad propia. Traicionados por uno de los suyos, el hechicero Zalazane, fueron expulsados de su hogar en las Islas del Eco y construyeron la aldea de pescadores de Sen'jin en la orilla del continente, sin poder recuperar jamás lo que Zalazane les había arrebatado.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "Durante cientos de años, los tauren no tuvieron tierra propia, perseguidos a lo largo de Kalimdor por los saqueadores centauros que dispersaron sus tribus en campamentos errantes.",
		full = "Durante cientos de años, los tauren no tuvieron tierra propia, perseguidos a lo largo de Kalimdor por los saqueadores centauros que dispersaron sus tribus en campamentos errantes. Cuando Thrall y sus orcos desembarcaron en estas costas, Cairne Pezuña de Sangre los contempló y vio en ellos espíritus afines, honorables y fuertes. Con la escolta de los orcos y su fuerza respaldándolo, Cairne condujo a su pueblo hasta el valle resguardado, rodeado de montañas por todos lados, y allí su tribu Pezuña de Sangre expulsó a los centauros de las praderas y por fin las hizo suyas.\n\nSobre la meseta que se alzaba por encima de la llanura, Cairne construyó Cima del Trueno, un refugio abierto a los tauren de todas las tribus, y con el tiempo los pueblos dispersos se unieron bajo su mando.\n\nLos pastos siguen verdes, las mesetas aún proyectan sus largas sombras sobre el Poblado Pezuña de Sangre, y todo tauren que alcanza la mayoría de edad debe todavía adentrarse en las llanuras salvajes para demostrar su valía en la Gran Cacería, como lo hicieron sus ancestros.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "Los Baldíos",
		short = "El polvo de este lugar no siempre fue polvo.",
		full = "El polvo de este lugar no siempre fue polvo. Antaño esto era un bosque, cuidado por los kaldorei que levantaron el puesto de Then'Ralore, y se dice que el semidiós Lo'Gosh se enfrentó aquí a la Legión Ardiente durante la Guerra de los Ancestros. El Gran Cataclismo acabó con todo aquello, y el valle verde se convirtió en la llanura abrasada por el sol que es hoy.\n\nDurante generaciones, los tauren recorrieron estas llanuras cazando kodos y truenagartos, buscando la sabiduría de la Madre Tierra, siempre acosados por los centauros, que los cazaban por diversión. Se defendían, pero nunca por amor a la guerra; cuando llegaban los hombres caballo, levantaban sus tiendas y seguían su camino antes que desperdiciar vidas. Un año de paz, un año de guerra: así era la vida de los tauren, hasta que los orcos de Thrall y los trols Lanza Negra desembarcaron y marcharon junto a los tauren Pezuña de Sangre contra los centauros. Tras la caída de la Legión en el Monte Hyjal, Thrall reclamó el este de Los Baldíos, expulsó a los jabaespines Crines de Acero y llamó a esa tierra Durotar, alzando Orgrimmar como su capital.\n\nEsta tierra guarda también penas más antiguas: se dice que un hombre llamado Dethorin encontró a su amada Allurana en brazos de otro, y que su grito arrancó de la arena el hacha Mutiladora, la misma hoja con la que la mató.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "Después de que el Gran Cataclismo quebrara el mundo, los elfos de la noche que quedaron se apartaron deliberadamente del resto del mundo.",
		full = "Después de que el Gran Cataclismo quebrara el mundo, los elfos de la noche que quedaron se apartaron deliberadamente del resto del mundo. Entre los humanos, Kalimdor sobrevivió solo como leyenda: una tierra que, según se decía, se había quebrado y hundido bajo las olas, sin ubicación ni forma conocidas.\n\nPero no estaba del todo perdida. Los elfos de la noche visitaron a los quel'dorei en los años que siguieron, y así los altos elfos de Quel'Thalas fueron los únicos que supieron que la leyenda era cierta.\n\nIncluso cuando llegó la Tercera Guerra, la mayoría de los humanos seguía negándose a creer que Kalimdor existiera, y entre los escépticos se contaba el propio embajador del Kirin Tor en la corte del rey Terenas. Solo unos pocos atendieron la advertencia de Medivh y zarparon hacia el oeste, entre ellos la nueva Horda de Thrall, seguida por la expedición de Jaina Valiente. Lo que encontraron no fue una leyenda, sino un continente entero, con hielo en el norte, desierto en el sur y elfos de la noche que aún defendían los bosques entre ambos.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Reinos del Este",
		short = "Los Reinos del Este no siempre fueron muchas tierras.",
		full = "Los Reinos del Este no siempre fueron muchas tierras. Antaño formaban parte de un solo continente, antes de que el Gran Cataclismo desgarrara el mundo y dejara atrás los fragmentos rotos que hoy se llaman Azeroth, Khaz Modan y Lordaeron, con Quel'Thalas aferrada al norte de esta última tierra destrozada, sin saber siquiera hoy si es un lugar propio o apenas un rincón de otro.\n\nA través de estos fragmentos, las montañas de Khaz Modan y Crestagrana se alzan como una columna vertebral en el corazón del continente, y a su alrededor perduran los pueblos antiguos: enanos y gnomos en sus profundos salones, humanos en sus reinos, altos elfos en sus bosques, y ahora los Renegados, alzados donde antes vivía el pueblo de Lordaeron. Orcos, goblins, nagas y ogros también han llegado a estas tierras, aunque ninguno de ellos nació en ellas.\n\nLas cicatrices de aquella primera ruptura siguen siendo la verdad de este lugar. Cada frontera, cada estrecho y cada franja de tierra anegada entre un reino y el siguiente recuerda que los Reinos del Este estuvieron alguna vez unidos, y que ya no lo están.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Montañas de Alterac",
		short = "La lluvia nunca deja de caer del todo sobre estas cumbres, y el cielo que las cubre siempre está gris. Antaño, las montañas coronaban la ciudad-estado de Alterac, que dominaba gran parte de las tierras del norte, y además daban cobijo a Dalaran.",
		full = "La lluvia nunca deja de caer del todo sobre estas cumbres, y el cielo que las cubre siempre está gris. Antaño, las montañas coronaban la ciudad-estado de Alterac, que dominaba gran parte de las tierras del norte, y además daban cobijo a Dalaran. Ambas han desaparecido, y lo que queda explica por qué tan pocos se atreven a subir hasta aquí.\n\nCuando terminó la Segunda Guerra, la Alianza de Lordaeron descubrió que los señores de Alterac habían pactado en secreto con la Horda, y envió un ejército a estas montañas para castigar a los traidores en su propio hogar. La ciudad cayó, su gente fue dispersada o encarcelada, y su linaje nunca recuperó el trono. Un príncipe posterior de aquella casa caída, Aliden Perenolde, se alzó en cambio como señor de bandidos y reunió a proscritos y vengativos en la Hermandad, una compañía de pícaros que aún domina Strahnbrad y recorre estas laderas buscando recuperar lo que su familia perdió.\n\nHoy, las ruinas de la Ciudad de Alterac pertenecen a los ogros Aplastacresta, y la Hermandad controla gran parte de lo que los ogros no dominan.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Tierras Altas de Arathi",
		short = "El rey Thoradin llegó a esta tierra árida porque un sueño le reveló que su pueblo prosperaría aquí, y sobre ella levantó Strom, la primera capital de una Arathor unida.",
		full = "El rey Thoradin llegó a esta tierra árida porque un sueño le reveló que su pueblo prosperaría aquí, y sobre ella levantó Strom, la primera capital de una Arathor unida. El terreno seco le sirvió como un muro de espinas que negaba a los trols del bosque de Amani la protección que necesitaban para sus emboscadas, y además levantó una segunda muralla. Durante mil años, Strom se mantuvo en el corazón del imperio, hasta que sus casas nobles se marcharon en busca de tierras más fértiles y los últimos descendientes de Thoradin partieron para fundar Ventormenta. Lo que quedó se convirtió en Stromgarde, gobernada desde entonces por el linaje Aterratrols.\n\nStromgarde ha caído desde entonces, invadida por los ogros y la Hermandad, y sus supervivientes fueron expulsados del castillo hacia un cañón que ahora llaman Refugio de la Zaga. Cerca se alza Sentencia, que antes fue un campamento donde la humanidad encerraba a sus prisioneros orcos, y que ahora está en manos de los propios orcos y fue rebautizada en honor a Orgrim Martillo Maldito.\n\nLa gran muralla de Thoradin se ha derrumbado hasta quedar convertida en una enorme ruina, y su castillo yace destrozado y en disputa, todavía codiciado por los ogros, la Hermandad y los últimos soldados de un reino que intenta recuperarlo.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Tierras Inhóspitas",
		short = "Las Tierras Inhóspitas son un desierto agrietado de tierra reseca, rocas dispersas y cañones sinuosos, rodeado de montañas por todas partes.",
		full = "Las Tierras Inhóspitas son un desierto agrietado de tierra reseca, rocas dispersas y cañones sinuosos, rodeado de montañas por todas partes. Poco sobrevive aquí aparte de coyotes, pumas y buitres.\n\nEn el norte se encuentran las ruinas de Uldaman, obra de los antiguos terráneos. Cuando fue desenterrada, ofreció las primeras pistas sobre el elevado origen de los enanos, y los buscadores de Forjaz llegaron en masa para registrar las ruinas en busca de artefactos de los titanes. Pero los troggs Grutacanto, despertados tras milenios de letargo, masacraron a los exploradores y ahora defienden con ferocidad la ciudad que robaron. Justo al sur de Uldaman se alza una gran fortaleza de los Hierro Negro, cuyos enanos combaten contra los ogros de la tribu Rotapolvo y contra los dracos que anidan entre las crías de dragón negro del este.\n\nMás tarde se fundó aquí Kargath, el único puesto de la Horda en Khaz Modan, levantado para que los orcos vigilaran a sus renegados parientes Roca Negra. El propio Jefe de Guerra Thrall envió a la Fuerza Expedicionaria de Kargath para dar caza a Rend Puño Negro.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Las Tierras Devastadas",
		short = "Las Tierras Devastadas hacen honor a su nombre. La arcilla roja que se pisa aquí fue antes tierra parda, parte de un oscuro pantano llamado la Ciénaga Negra, antes de que la Horda orca abriera aquí el Portal Oscuro e irrumpiera en Azeroth.",
		full = "Las Tierras Devastadas hacen honor a su nombre. La arcilla roja que se pisa aquí fue antes tierra parda, parte de un oscuro pantano llamado la Ciénaga Negra, antes de que la Horda orca abriera aquí el Portal Oscuro e irrumpiera en Azeroth. La magia que se filtró aquel día abrasó el suelo hasta volverlo rojo y lo mató para siempre. Hoy aquí no crece nada salvo matorrales resistentes del desierto, y solo viven criaturas resistentes del desierto: basiliscos, escorpiones y hienas.\n\nEl archimago Khadgar y el Kirin Tor levantaron el Castillo de Nethergarde para vigilar las ruinas del portal y asegurarse de que nada volviera a cruzarlo. La paz duró dos años, hasta que la Horda de Draenor reabrió el Portal y sitió el castillo. Cuando el ritual de Ner'zhul comenzó a desgarrar Draenor, Khadgar y los demás magos usaron la Calavera de Gul'dan para reducir a pedazos el marco de piedra del Portal desde el otro lado, cortando para siempre el puente entre los mundos.\n\nHoy, los magos y paladines de Nethergarde siguen montando su sombría guardia sobre el Portal muerto: una comunidad cerrada y adusta que no confía en nadie ni perdona ningún descuido, el único refugio que puede encontrarse en una tierra donde las tormentas del mar oriental se escurren sobre el suelo calcinado antes de poder hacer algún bien.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Claros de Tirisfal",
		short = "El cielo sobre los Claros de Tirisfal lleva años teñido de un verde enfermizo, y los árboles se aferran a la poca vida que la peste les dejó.",
		full = "El cielo sobre los Claros de Tirisfal lleva años teñido de un verde enfermizo, y los árboles se aferran a la poca vida que la peste les dejó. Antaño, estas eran granjas pacíficas bajo el reinado del rey Terenas, donde generaciones vivían tranquilas entre molinos y campos de calabazas. Todo terminó cuando Arthas Menethil saqueó Lordaeron y extendió la peste por la campiña, matando a su gente y alzándola como esclava del Rey Exánime. Las fosas comunes aún señalan los lugares donde los muertos eran demasiados para enterrarlos como es debido. Fue cerca de la Hacienda Balnir, meses después, donde Sylvanas Brisaveloz volvió a sus almas en pena contra Arthas y clavó una flecha envenenada en el caballero de la Muerte, antes de que los esqueletos de Kel'Thuzad la obligaran a huir.\n\nDe aquella ruina surgieron los Renegados, los muertos con libre albedrío de Sylvanas, que reclamaron esta tierra como propia. Sus enemigos nunca se marcharon: la Cruzada Escarlata ocupa el antiguo Monasterio Escarlata en el norte, fanáticos que queman y persiguen a todo aquel que no sea humano.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Bosque de Argénteos",
		short = "El Bosque de Argénteos, o simplemente Argénteos, es un bosque vasto y antiguo que se extiende a lo largo de la escarpada costa occidental de Lordaeron. El terreno va de bastante llano a ondulado, y se encuentra enclavado entre montañas aún más altas.",
		full = "El Bosque de Argénteos, o simplemente Argénteos, es un bosque vasto y antiguo que se extiende a lo largo de la escarpada costa occidental de Lordaeron. El terreno va de bastante llano a ondulado, y se encuentra enclavado entre montañas aún más altas. El bosque guarda un silencio inquietante, roto solo por algún aullido antinatural que resuena de vez en cuando entre los árboles. Los salientes cubiertos de musgo tiemblan con la brisa fría, y todos los árboles están enfermos o moribundos. Granjas en ruinas y minas abandonadas salpican la región, ahora hogar de los habitantes más oscuros del bosque.\n\nEsta arboleda es salvaje y está embrujada, y se caracteriza por sus altos pinos de corteza plateada que se alzan sobre colinas cubiertas de hierba. La Alianza protegió en otro tiempo el Bosque de Argénteos, cuando era frondoso y lleno de vida. Ahora el lugar está envuelto en nieblas fantasmales. Los Renegados controlan el norte del bosque y se enfrentan constantemente a los miserables gnolls Putrepellejo. Lo que queda de la población humana mantiene el control del sur del bosque, pero están desesperados y sus fuerzas escasean. Dalaran envía con frecuencia expediciones a Argénteos para defender a esta gente y estudiar la peste de los no-muertos y la maldición huargen, una misteriosa aflicción que hace que sus víctimas se transformen en huargen sanguinarios y licántropos cuando sale la luna.\n\nGilneas y las Laderas de Trabalomas limitan con el bosque por el sur, mientras que los Claros de Tirisfal se extienden al norte. El Lago Lordamere marca la frontera oriental de Argénteos.\n\nAunque el territorio pertenece a los Renegados, su dominio es disputado por los magos de Dalaran y por agentes de la Plaga que se han apoderado de algunos de los campos y granjas en ruinas. Los gnolls Putrepellejo operan desde la misteriosa Isla de Fenris y atacan con ferocidad a cualquiera que se atreva a acercarse a sus asuntos. Al suroeste se encuentra la Aldea Piroleña, cuyos habitantes han caído bajo la maldición del archimago Arugal y se transforman en huargen sanguinarios por la noche. Arugal habita en las oscuras torres cercanas del Castillo de Colmillo Oscuro.\n\nEl Bosque de Argénteos es escenario frecuente de batallas, pues las fuerzas de la Alianza de Costasur viajan a este bosque abandonado para atacar el Sepulcro o entrar en Colmillo Oscuro. Es el límite de la patria de los Renegados, y el punto más meridional donde pueden verse en la vegetación los efectos de la peste de los no-muertos.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Tierras de la Peste del Oeste",
		short = "Antaño, estas eran las tierras de cultivo más hermosas del norte de Lordaeron, boscosas y verdes, que llenaban los graneros del reino desde Andorhal y eran gobernadas desde el salón de Vega del Amparo.",
		full = "Antaño, estas eran las tierras de cultivo más hermosas del norte de Lordaeron, boscosas y verdes, que llenaban los graneros del reino desde Andorhal y eran gobernadas desde el salón de Vega del Amparo. Aquella prosperidad se convirtió en el arma que se usó para destruirlas.\n\nSiguiendo el designio del Rey Exánime, el Culto de los Malditos llevó sus energías de la peste hacia el sur en calderas portátiles, que escondió en aldeas de cultistas leales, y colocó las cuatro más grandes en los propios campos de Andorhal. El mismo grano quedó contaminado, y salió hacia todo Lordaeron en carretas que nadie pensó en revisar. La gente que comió su propio pan enfermó, murió y se alzó de nuevo como esclava del Rey Exánime. Los bosques nunca se recuperaron. Los pinos se yerguen grises, con las agujas pardas, bajo una bruma de niebla enfermiza, y sus troncos hinchados de excrecencias tumorales.\n\nEl orden que queda se rescató tras el colapso del reino, cuando la Cruzada Escarlata tomó la Fortaleza de Mardenholde en Vega del Amparo y desde allí lanzó sus ataques contra los no-muertos que dominan el resto de la tierra. En medio de todo ello, solo un lugar conserva algo de paz: la Tumba de Uther, consagrada a Uther el Iluminado, un suelo que la plaga nunca ha tocado.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Tierras de la Peste del Este",
		short = "Antaño, esta tierra era de cultivo: las aldeas de los Bosques del Este se repartían alrededor de Stratholme, la segunda ciudad de Lordaeron. Nada de eso queda.",
		full = "Antaño, esta tierra era de cultivo: las aldeas de los Bosques del Este se repartían alrededor de Stratholme, la segunda ciudad de Lordaeron. Nada de eso queda. Ahora el suelo está pardo y enfermo, los árboles se han hinchado hasta parecer hongos y el aire está cargado de una niebla anaranjada.\n\nFue a Stratholme adonde llegó el príncipe Arthas, buscando el origen de una peste que ya había infectado a los habitantes de la ciudad. Lord Uther, maestro de la Mano de Plata, se negó a permitir que purgara la ciudad. Arthas lo despojó del mando, disolvió la Mano de Plata en ese mismo momento y pasó a espada él mismo a los habitantes de Stratholme antes que dejar que se alzaran como parte de la Plaga. Y no se detuvo ahí: persiguió al señor del terror Mal'Ganis hasta el norte, regresó convertido en caballero de la Muerte y mató a su propio padre, poniendo fin al reino de Lordaeron.\n\nAlexandros Mograine formó una Cruzada con los restos de la Mano de Plata para recuperar las ruinas, y tomó la Mano de Tyr y la mitad de Stratholme antes de que su muerte dividiera su orden en El Alba Argenta y la Cruzada Escarlata, que aún ocupa estos campos, combatiendo sin fin a la Plaga y sin dar la bienvenida a nadie más.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Laderas de Trabalomas",
		short = "El suelo de Trabalomas es fértil y sus colinas son verdes, y los viajeros dicen que así era todo Lordaeron antes de que llegara la Peste.",
		full = "El suelo de Trabalomas es fértil y sus colinas son verdes, y los viajeros dicen que así era todo Lordaeron antes de que llegara la Peste. Esa es su crueldad tanto como su consuelo: la tierra recuerda lo que se perdió en todas partes, mientras quienes la ocupan libran la misma guerra que arruinó el resto.\n\nAl comienzo de la Segunda Guerra, los saqueadores orcos atacaron sus pueblos costeros, y el propio Orgrim Martillo Maldito cabalgó contra el Castillo de Durnholde para liberar a Zul'jin de sus celdas. Décadas después fue Thrall quien cruzó estas colinas, reuniendo a los clanes orcos dispersos antes de colarse de noche en Costasur para robar sus barcos y llevar a la nueva Horda a través del mar hasta Kalimdor.\n\nLo que empezaron los orcos, lo han continuado los Renegados. Reclamaron el Molino Tarren como su posesión más meridional y lo convirtieron en una base de operaciones contra los humanos de Costasur y los Campos de Trabalomas, que resistieron con firmeza en nombre de la Alianza.\n\nAhora hay pinares repartidos entre las tierras de cultivo, y los caminos aún cruzan los pastizales hacia los lúgubres asentamientos de los Renegados en el norte, como si la tierra misma siguiera esperando a ver qué bando se queda con ella.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "Tierras del Interior",
		short = "Después de la guerra de los Tres Martillos, los enanos Martillo Salvaje abandonaron sus túneles de Grim Batol y viajaron al norte, donde construyeron sus hogares en la superficie, en Pico Nidal.",
		full = "Después de la guerra de los Tres Martillos, los enanos Martillo Salvaje abandonaron sus túneles de Grim Batol y viajaron al norte, donde construyeron sus hogares en la superficie, en Pico Nidal. Dejaron la piedra y la forja por el cielo y las alas, y se unieron tan estrechamente a los grifos salvajes de la región que levantaron un gran grifo de piedra en su propia ciudad para honrar ese vínculo. Los trols del bosque que ya ocupaban esta tierra, restos del otrora gran Imperio Amani, vieron a los enanos como intrusos en su tierra ancestral y atacaban los nidos siempre que podían.\n\nCuando la Horda irrumpió en la región durante la Segunda Guerra, el señor feudal Kurdran Martillo Salvaje y sus jinetes, que hasta entonces ni siquiera sabían que existían tales invasores, cayeron desde el cielo sobre las columnas orcas con martillos cargados de tormenta y las acosaron sin descanso. Orgrim Martillo Maldito esperaba atraer las fuerzas de la Alianza hacia las Tierras del Interior para poder atacar Quel'Thalas sin oposición, pero Anduin Lothar descubrió el plan y cabalgó él mismo al lado de Kurdran, y juntos derrotaron a los invasores y los obligaron a retroceder hasta las Montañas de Alterac. Por ello, Kurdran comprometió la ayuda de su pueblo a la Alianza.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "La nieve cubre en espesas capas Dun Morogh, rodeada por todas partes de las montañas de Khaz Modan, y sus pasos siempre están vigilados por tropas enanas.",
		full = "La nieve cubre en espesas capas Dun Morogh, rodeada por todas partes de las montañas de Khaz Modan, y sus pasos siempre están vigilados por tropas enanas. Antes de pertenecer a nadie más, estas montañas pertenecieron a los trols de hielo Peloescarcha, que se habían asentado en la región tras separarse del Imperio Drakkari en tiempos remotos.\n\nEso cambió cuando los primeros gnomos salieron de Uldaman y usaron su ingenio para sobrevivir tanto al frío como a los trols, excavando moradas fortificadas en lo profundo de las cumbres. Quinientos años después, los enanos los siguieron al salir de Uldaman, atraídos por las mismas montañas que habían divisado en el horizonte, y levantaron Forjaz bajo la más alta de ellas. Al encontrar a los gnomos ya asentados en las cercanías, ambos pueblos forjaron una amistad que nunca se ha roto: los enanos prestaron su fuerza para construir Gnomeregan, y los gnomos compartieron los secretos de sus máquinas. Juntos, sus ejércitos derrotaron a los trols Peloescarcha y obligaron a los supervivientes a replegarse en las colinas, acabando para siempre con el dominio de los trols sobre esta tierra.\n\nGnomeregan ya no existe, está en ruinas, y su pueblo se hacina en Forjaz en busca de refugio.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "La Garganta de Fuego",
		short = "Antaño, esta era una tierra verde, parte de las Montañas Crestagrana, hasta que el suelo mismo se desgarró hace más de doscientos treinta años.",
		full = "Antaño, esta era una tierra verde, parte de las Montañas Crestagrana, hasta que el suelo mismo se desgarró hace más de doscientos treinta años.\n\nDurante la guerra de los Tres Martillos, el hechicero y señor feudal Thaurissan, de los enanos Hierro Negro, buscó un arma para derrotar a sus enemigos. Él y siete de sus enanos de mayor confianza alcanzaron las profundidades del mundo e invocaron poderes que debieron seguir dormidos. Lo que respondió no fue un sirviente sino un amo: el antiguo Señor del Fuego, Ragnaros. Su despertar arrancó la Montaña Roca Negra de la tierra, ennegreció el terreno a lo largo de kilómetros y aplastó bajo ella hasta los escombros la capital Hierro Negro de Thaurissan. Las estepas abrasadas del sur pasaron a llamarse las Estepas Ardientes; este valle devastado del norte se convirtió en la Garganta de Fuego.\n\nNo todos los Hierro Negro siguieron siendo leales a su clan tras la catástrofe. Algunos se separaron, se hicieron llamar la Hermandad del Torio y construyeron el Puesto del Torio con vistas a la gran excavación que sus antiguos parientes habían abierto en el fondo del valle, vigilando desde lo alto los trabajos de los Hierro Negro.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Las Estepas Ardientes",
		short = "El cielo sobre las Estepas Ardientes nunca pierde su tono rojizo, iluminado por las erupciones esporádicas de la Montaña Roca Negra, y el suelo nunca se enfría.",
		full = "El cielo sobre las Estepas Ardientes nunca pierde su tono rojizo, iluminado por las erupciones esporádicas de la Montaña Roca Negra, y el suelo nunca se enfría. Doscientos años antes de que se abriera el Portal Oscuro, los enanos Hierro Negro llegaron aquí exiliados de Forjaz. Su hechicero y señor feudal, Thaurissan, intentó invocar siervos elementales para ganar la guerra de los Tres Martillos contra los clanes Barbabronce y Martillo Salvaje. Lo que respondió no fue un siervo, sino Ragnaros, el Señor del Fuego, a quien los titanes habían desterrado tiempo atrás. Su llegada fundió las montañas a su alrededor, alzó un volcán en el centro de la explosión y destruyó a los enanos que lo habían invocado. Lo que quedaba al norte de aquel nuevo pico se convirtió en la Garganta de Fuego; lo que quedaba al sur, en las Estepas Ardientes, marcadas desde entonces por las cicatrices.\n\nLos orcos se asentaron en las laderas del volcán durante la Primera Guerra y mantuvieron la Cumbre de Roca Negra como bastión durante la Segunda. Los orcos Roca Negra regresaron después y siguen allí, fieles a las antiguas y brutales costumbres de antes de la tregua de Thrall. Los dragones negros al mando de Nefarian dominan los niveles superiores de la cumbre, y se dice que Ragnaros aún medita en algún lugar bajo todo ello.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Bosque de Elwynn",
		short = "Cuando los orcos llegaron durante la Primera Guerra, miles de ellos marcharon a través de Elwynn para rodear Ventormenta, aislándola de todo salvo del mar.",
		full = "Cuando los orcos llegaron durante la Primera Guerra, miles de ellos marcharon a través de Elwynn para rodear Ventormenta, aislándola de todo salvo del mar. El caballero campeón Anduin Lothar encabezó a los Caballeros de Ventormenta en una carga a través del propio bosque, atacando por sorpresa a la retaguardia orca y dispersándola. Eso le dio tiempo a la ciudad, pero no el suficiente. El Jefe de Guerra Puño Negro pronto tomó Villadorada y Arroyo de la Luna, los últimos pueblos que se interponían entre la Horda y el rey, y el Castillo de Ventormenta fue saqueado. Lothar condujo a los supervivientes hasta el mar y de ahí a Lordaeron, y las ruinas de la ciudad pertenecieron durante un tiempo al clan Cazatormentas. Algunas catapultas orcas rotas aún se pudren dispersas por la región, los únicos recuerdos que quedan de aquella ocupación.\n\nLos Viñedos de Villanorte, al este de la ciudad, fueron en otro tiempo el orgullo de los granjeros de Ventormenta. Cuando la Hermandad de los Albañiles se quedó sin cobrar los años que dedicó a reconstruir la capital en ruinas, y los nobles la disolvieron antes que saldar la deuda, la furia del maestro del gremio Edwin VanCleef se extendió en disturbios que costaron la vida a la reina Tiffin Ellerian Wrynn y dieron origen a la Hermandad Defias. La Hermandad expulsó a los granjeros de Villanorte y ocupó sus campos.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Paso de la Muerte",
		short = "El Paso de la Muerte atraviesa las montañas del centro de Azeroth y une el Bosque del Ocaso con el Pantano de las Penas. Hace una veintena de años se lo consideraba parte de las Montañas Crestagrana.",
		full = "El Paso de la Muerte atraviesa las montañas del centro de Azeroth y une el Bosque del Ocaso con el Pantano de las Penas. Hace una veintena de años se lo consideraba parte de las Montañas Crestagrana.\n\nLa Torre de Marfil de Karazhan, antigua sede del poder del oscuro hechicero Medivh, se alza en el centro de esta región escarpada y filtra magia maligna en la tierra. Los árboles están petrificados y sin hojas, y un viento terrible gime a través del cañón. Ogros, demonios, no-muertos y algunos gitanos humanos vagan por el interior, y se murmura que una nueva fuerza se ha apoderado de la Torre de Marfil y que los ogros y los demonios están bajo su dominio.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Bosque del Ocaso",
		short = "Un manto de noche antinatural cubre el Bosque del Ocaso, y jamás se ha levantado.",
		full = "Un manto de noche antinatural cubre el Bosque del Ocaso, y jamás se ha levantado. Lo que antes fue una hermosa extensión del Bosque de Elwynn es ahora una tierra maldita y moribunda: los árboles crecieron retorcidos bajo la niebla negra, los muertos se alzaron de sus tumbas y los huargen llegaron sigilosos junto con la propia oscuridad, atraídos por los efectos de la Guadaña de Elune. Los ogros que avanzan desde el Paso de la Muerte no han hecho más que ahondar la miseria.\n\nHace mucho que la protección de Ventormenta dejó de significar algo aquí, y quienes permanecen han aprendido a defenderse sin ella. Su milicia, la Guardia Nocturna, patrulla los caminos y protege Villa Oscura de todo lo que se mueve entre las sombras: guerreros esqueléticos y necrófagos, huargen feroces y, además, hombres de los Defias.\n\nEn el corazón del bosque se encuentra el cráter de un volcán extinto hace mucho, envuelto en un crepúsculo más suave que la oscuridad que lo rodea. En su interior se alza uno de los Grandes Árboles, cuyas raíces se extienden hacia el Sueño Esmeralda, y la influencia de los druidas durmientes tiñe todo lo que crece a su alrededor. Más allá se extienden granjas abandonadas y las amplias tumbas del Cementerio del Cerro del Cuervo, que se llenan año tras año desde que cayó la oscuridad.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "Las aguas de Loch Modan descansan acunadas entre piedra gris, contenidas por la Presa de las Tres Cabezas, una obra de ingeniería enana que ninguna otra estructura de Azeroth ha logrado igualar jamás.",
		full = "Las aguas de Loch Modan descansan acunadas entre piedra gris, contenidas por la Presa de las Tres Cabezas, una obra de ingeniería enana que ninguna otra estructura de Azeroth ha logrado igualar jamás. Las montañas se alzan escarpadas por todos lados, con escasos bosques de pinos y abedules, y el lago permanece quieto y silencioso, como si nada lo hubiera perturbado nunca.\n\nSin embargo, el lago fue un campo de batalla. Durante la Segunda Guerra, los orcos de la Horda irrumpieron en la región y resistieron aquí contra la Alianza. Forjaz aguantó. Sus enanos rechazaron a los orcos y recuperaron Loch Modan, pero los restos de aquella guerra nunca se retiraron del todo: catapultas rotas y balistas destrozadas siguen dispersas por el fondo del lago y sus islas, medio hundidas, la única prueba que queda de que estas aguas tranquilas fueron alguna vez un matadero.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Montañas Crestagrana",
		short = "Las Montañas Crestagrana se encuentran al este del Bosque de Elwynn, al noreste del Bosque del Ocaso y al sur de las Estepas Ardientes.",
		full = "Las Montañas Crestagrana se encuentran al este del Bosque de Elwynn, al noreste del Bosque del Ocaso y al sur de las Estepas Ardientes.\n\nRegión idílica de ríos caudalosos, olmos imponentes y terrenos cada vez más altos, Crestagrana está bajo la protección de Ventormenta, aunque desde la Segunda Guerra es técnicamente independiente. Sigue siendo una de las últimas regiones pacíficas de Azeroth; su gente vive tranquila y satisfecha, y abastece a Ventormenta de madera, pescado y cosechas. Sin embargo, la paz no es perfecta: una fuerza de orcos Roca Negra procedente de las Estepas Ardientes ocupa el Fuerte de Petravista, aunque hasta ahora no se ha metido con nadie. Comparada con la ruina de los Páramos de Poniente, Crestagrana aún se mantiene en pie.\n\nEn la orilla norte del Lago Sempiterno se alza el pueblo de Villa del Lago, asediado por gnolls y orcos Roca Negra que bajan de las colinas circundantes. Al sur, el cruce de caminos conocido como Tres Caminos une Villa del Lago con Elwynn y el Bosque del Ocaso, y, por el Camino del Lago, con el Fuerte de Petravista, una ruta dominada por crías de dragón, gnolls, múrlocs y bestias salvajes.\n\nLa superficie del lago parece bastante tranquila, pero los múrlocs acechan bajo ella, y persisten los rumores de un monstruo marino en sus profundidades.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Vega de Tuercespina",
		short = "La Vega de Tuercespina es una vasta selva al sur del Bosque del Ocaso. Los trols de la selva patrullan esta húmeda y sofocante jungla, y los nagas cazan a lo largo de sus costas, mientras que las enredaderas espinosas y las bestias hacen peligroso el viaje.",
		full = "La Vega de Tuercespina es una vasta selva al sur del Bosque del Ocaso. Los trols de la selva patrullan esta húmeda y sofocante jungla, y los nagas cazan a lo largo de sus costas, mientras que las enredaderas espinosas y las bestias hacen peligroso el viaje.\n\nLa vega fue antaño el corazón del Imperio Gurubashi, cuyas grandes ciudades se alzaban por toda la región. Tras la caída del imperio, esas ciudades se desmoronaron hasta quedar en ruinas, aunque los trols aún habitan entre ellas. Zul'Gurub, en el noreste, fue en otro tiempo la capital Gurubashi.\n\nBahía del Botín fue originalmente un pequeño pueblo portuario fundado por humanos, hasta que los trols lo invadieron. Más tarde, los goblins del Cártel Bonvapor expulsaron a los trols de la cala y la reclamaron como suya, convirtiéndola en su centro de operaciones en los Reinos del Este.\n\nEn el norte se alza un recinto levantado por la expedición del coronel Kurzen. Allí, la mente del coronel fue dominada por un mago ogro, Mai'Zoth, que usó un artefacto llamado el Ojo de la Mente para doblegar la voluntad de Kurzen y dar órdenes a sus hombres. Varios soldados de Kurzen se rebelaron contra su comandante poseído y huyeron hacia el oeste, donde fundaron un campamento rebelde para desafiarlo.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Pantano de las Penas",
		short = "Bajo las aguas negras del pantano yace un templo más antiguo que la pena que dio nombre a este lugar.",
		full = "Bajo las aguas negras del pantano yace un templo más antiguo que la pena que dio nombre a este lugar. Cuando cayó el Imperio Gurubashi, un grupo renegado de trols llamados Atal'ai huyó al pantano y levantó el Templo de Atal'Hakkar, donde practicaban ritos macabros para devolver al mundo a su loa oscuro, Hakkar el Cazador de Almas. Su magia retorció las plantas y las bestias alrededor del templo hasta que la corrupción no pudo pasar desapercibida. Ysera, señora de los sueños, se enteró de las ambiciones del culto y volvió su poder contra ellos, hundiendo el templo bajo la ciénaga más grande antes de que Hakkar pudiera regresar. Pero no confiaba en que los trols abandonaran a su dios para siempre. Dispuso que su consorte Eranikus y una hueste de dragones verdes montaran guardia eterna sobre las ruinas, para que jamás volvieran a usarse para desatar semejante mal sobre el mundo. Los dracónidos verdes aún patrullan estos pantanos por orden suya, y el templo hundido sigue sellado bajo el agua, vigilado en lugar de destruido.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Páramos de Poniente",
		short = "Ahora el viento corre sin obstáculos sobre los campos de los Páramos de Poniente, pues ya no queda nada alto que lo frene. Antaño, esta era el granero de Ventormenta, que alimentó al joven reino durante generaciones.",
		full = "Ahora el viento corre sin obstáculos sobre los campos de los Páramos de Poniente, pues ya no queda nada alto que lo frene. Antaño, esta era el granero de Ventormenta, que alimentó al joven reino durante generaciones.\n\nCuando la Hermandad de los Albañiles se quedó sin cobrar por reconstruir Ventormenta después de la Segunda Guerra, y la guardia se volvió contra sus protestas, el maestro del gremio Edwin VanCleef llevó a sus hombres a esconderse en el campo antes que enfrentar la justicia del rey Varian. Allí se convirtieron en la Hermandad Defias, y bajo un granero de Arroyo de la Luna, VanCleef encontró una vieja red de minas lo bastante profunda como para ocultar la construcción de un arma destinada a incendiar Ventormenta desde el mar. Expulsó a los granjeros, contrató a gnolls Zarparrío para dominar la tierra e hizo que sus hombres quemaran los campos y salaran la tierra para que nada volviera a crecer allí.\n\nVentormenta, con sus arcas vacías, dejó que los Páramos de Poniente se las arreglaran solos. Solo Gryan Mantorrecio respondió, formando la Milicia Popular en la Colina del Centinela cuando ningún ejército acudió.\n\nLos campos que él saló no se lo han perdonado a los Páramos de Poniente. La hierba sigue creciendo amarilla y rala donde antes el trigo llegaba a la altura de los hombros.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Los Humedales",
		short = "Un pantano frío y gris se extiende bajo la presa, con niebla sobre sus ríos y estanques, montañas que lo encierran por tres lados y el mar abierto al oeste.",
		full = "Un pantano frío y gris se extiende bajo la presa, con niebla sobre sus ríos y estanques, montañas que lo encierran por tres lados y el mar abierto al oeste. Hay escombros dispersos por todas partes, restos de fortalezas enanas que antaño dominaban este terreno. Ahora lo dominan múrlocs, bestias salvajes y orcos renegados, y el Puerto de Menethil es el único bastión verdadero de la Alianza aquí.\n\nEse puerto no siempre fue territorio de la Alianza. Cuando comenzó la Segunda Guerra, Orgrim Martillo Maldito construyó su flota de invasión en una pequeña isla de la Bahía de Baradin, para que sus barcos pudieran atacar las costas de Lordaeron sin enfrentarse a sus defensas terrestres. Los Humedales pagaron el precio: los orcos y los dragones se alimentaron en abundancia de la tierra, y la caza escaseó. Tras la guerra, el puerto fue reconstruido y rebautizado como Puerto de Menethil, en honor a Terenas Menethil II.\n\nDespués llegó la caída de Grim Batol. El Vuelo Rojo, esclavizado para servir allí al clan Faucedraco, se volvió contra sus captores en cuanto fue liberado, y el clan quedó destrozado, con sus supervivientes dispersos por las tierras salvajes. Alexstrasza consideró que era carga de su vuelo mantener sellada la montaña, y desde entonces los dragones rojos montan guardia sobre ella.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "Cuando Malfurion Tempestira desapareció en el Sueño Esmeralda, el archidruida Fandral Corzocelada asumió el liderazgo del Círculo Cenarion en su lugar y convenció al Círculo de los Ancestros de que había llegado el momento de hacer crecer un nuevo Árbol del Mundo y recuperar la inmortalidad que los elfos de la noche habían perdido.",
		full = "Cuando Malfurion Tempestira desapareció en el Sueño Esmeralda, el archidruida Fandral Corzocelada asumió el liderazgo del Círculo Cenarion en su lugar y convenció al Círculo de los Ancestros de que había llegado el momento de hacer crecer un nuevo Árbol del Mundo y recuperar la inmortalidad que los elfos de la noche habían perdido. En el Mar de la Bruma alzaron Teldrassil, corona de la tierra, y construyeron Darnassus entre sus ramas. Pero Nozdormu, que había bendecido el primer Árbol del Mundo, se negó a bendecir este, pues consideró arrogante aquel deseo, y la inmortalidad que buscaban los elfos de la noche nunca llegó.\n\nCon el tiempo, la tierra en lo alto de Teldrassil cayó bajo una presencia siniestra. Los fúrbolgs y los grell de sus bosques enloquecieron, aparecieron sátiros entre los árboles, y las grandes tortugas y los tiburones trilladores que antes nadaban en las aguas alrededor del árbol huyeron para varar y morir en las playas de Costa Oscura. El origen de esta corrupción sigue siendo un misterio, y Malfurion no ha regresado del Sueño para descubrirlo.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Costa Oscura",
		short = "Una niebla gris cubre esta costa la mayor parte del tiempo, y los elfos de la noche la han tomado desde hace mucho como una advertencia.",
		full = "Una niebla gris cubre esta costa la mayor parte del tiempo, y los elfos de la noche la han tomado desde hace mucho como una advertencia. La lluvia y la roca hacen que la tierra sea poco acogedora, y todos los intentos de colonizarla más allá del puesto comercial de Auberdine han fracasado.\n\nHace diez mil años, aquí se alzaban las ciudades gemelas de Ameth'Aran y Bashal'Aran, gobernadas por Athrikus Narassin. Cuando la Guerra de los Ancestros quebró el mundo y llegó el Gran Cataclismo, Athrikus juró a su pueblo que lo salvaría. Cumplió su promesa al pie de la letra, pero traicionó su espíritu: encerró sus almas en gemas, diciéndoles que eso era la vida eterna, mientras en realidad las drenaba para alimentar su propio poder. Las ciudades quedaron en ruinas, y lo que camina hoy entre sus piedras no descansa del todo en paz.\n\nDespués de la Tercera Guerra, Fandral Corzocelada trajo a Costa Oscura a druidas del Círculo Cenarion y plantó un nuevo Árbol del Mundo, Teldrassil, frente a esta costa.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Vallefresno",
		short = "Vallefresno es un bosque antiguo, lleno de árboles viejos y de magia antigua, y nunca ha dejado de ser objeto de disputa.",
		full = "Vallefresno es un bosque antiguo, lleno de árboles viejos y de magia antigua, y nunca ha dejado de ser objeto de disputa.\n\nLos orcos del clan Grito de Guerra llegaron aquí primero como leñadores. Los goblins al mando de Neeloc Tacañón despojaron los árboles hasta que los fúrbolgs locales los hicieron retroceder, y Grommash Grito Infernal derrotó a su vez a los fúrbolgs y a las centinelas para conservar la ayuda de los goblins. El propio Cenarius acudió para restaurar lo que había sido talado, y le costó la vida: los amos de la Legión Ardiente convirtieron su confianza en una trampa, y Grommash lo abatió.\n\nLo peor llegó cuando la Legión marchó con todas sus fuerzas sobre Vallefresno. Los infernales de Archimonde cayeron ardiendo del cielo, y los no-muertos y los demonios irrumpieron desde el este, arrollando a los ejércitos divididos de elfos de la noche, orcos y humanos por igual antes de avanzar hacia el Monte Hyjal. Tyrande Susurravientos despertó a Malfurion del Sueño Esmeralda y él encontró el bosque que recordaba consumido por el fuego vil y una plaga asfixiante.\n\nAquella vieja contienda nunca terminó. Los elfos de la noche aún ocupan Astranaar y sus refugios dispersos; la Horda ha llevado sus campamentos Grito de Guerra hasta lo profundo del sur y el este, talando madera y haciendo retroceder a las centinelas. Ninguno de los dos bandos ha terminado nunca la lucha por estos bosques.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Las Mil Agujas",
		short = "El cañón es profundo y seco, y su fondo se pierde entre imponentes mesetas hasta que, al este, se abre al Desierto de Sal, una gran salina bajo un cielo inmenso.",
		full = "El cañón es profundo y seco, y su fondo se pierde entre imponentes mesetas hasta que, al este, se abre al Desierto de Sal, una gran salina bajo un cielo inmenso. El amanecer visto desde el Poblado Viento Libre o desde las alturas que rodean la Cumbre de la Nube Negra es un espectáculo asombroso sobre una tierra tan yerma. El druida Quentin se ha preguntado si la dura sequedad de este lugar, tan cerca de la exuberante selva de la vecina Feralas, no será en absoluto algo natural, sino la huella de alguna extraña magia obrada sobre la tierra.\n\nLas altas mesetas pertenecen a los tauren, y el Poblado Viento Libre es su bastión entre ellas. No han conservado este territorio sin oposición. Los centauros de la zona los acosaban y, peor aún, sus propios parientes de la tribu Tótem Siniestro se volvieron contra ellos, de modo que los tauren del Poblado Viento Libre se vieron obligados a luchar tribu contra tribu por las tierras altas. Solo con la ayuda de la Horda lograron hacer retroceder a los centauros y a los Tótem Siniestro.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Sierra Espolón",
		short = "La Cima del Espolón siempre perteneció a los espíritus antes que a cualquier pueblo.",
		full = "La Cima del Espolón siempre perteneció a los espíritus antes que a cualquier pueblo. Los elfos de la noche mantienen un túmulo y un claro en su cumbre, donde se comunican con la naturaleza, y los tauren también la consideran sagrada, pues fue aquí donde el Oráculo inmortal contempló en otro tiempo los hilos del destino mientras la Madre Tierra los tejía. Cuenta la leyenda que los primeros tauren que se asentaron en estas montañas llevaron tótems en llamas hasta los riscos más altos y encendieron hogueras en honor a An'she para hacer retroceder la oscuridad que se aferraba a la piedra.\n\nMás abajo en la montaña, hace mucho tiempo, Elune bendijo una fuente con el don de la salud. Más tarde, las arpías se apoderaron de los picos cercanos, capturaron a los dracoleones que anidaban allí y contaminaron las aguas de la fuente. Thrall se enfrentó a ellas, con Cairne Pezuña de Sangre y sus tauren a su lado, y derrotó a una banda de centauros para obtener un Glifo de Purificación y limpiar lo que las arpías habían corrompido. Los dracoleones liberados los llevaron hasta la propia Cima.\n\nAquella antigua paz con la tierra ha desaparecido en el sur. Ventura y Cía. ha arrasado el Risco Cortaviento: taló sus árboles, llenó el aire de hollín y contaminó el agua con aceite y desechos, hasta que los espíritus de la montaña clamaron con tanta fuerza que los chamanes los oyeron desde tan lejos como Orgrimmar.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Desolace",
		short = "Theradras, hija de Therazane la Madre Piedra, dormía antaño bajo una fértil pradera.",
		full = "Theradras, hija de Therazane la Madre Piedra, dormía antaño bajo una fértil pradera. Los chamanes tauren, convencidos de que la propia Madre Tierra habitaba debajo, la llamaron durante décadas hasta que por fin algo respondió; no fue la Madre Tierra, sino Theradras, arrancada con furia de su sueño. Se alimentó de la tierra para restaurar su forma debilitada, y los prados murieron en un instante. Los tauren llamaron Desolace a lo que quedó.\n\nZaetar, hijo del señor del bosque Cenarius, vino a someterla, pero en lugar de eso se enamoró de ella, y ella le correspondió. De su unión nacieron los centauros, y su primer acto fue asesinar a su propio padre. Se multiplicaron rápidamente y expulsaron a los tauren de la tierra, dando comienzo a siglos de guerra entre ambas razas.\n\nTheradras aún habita en Maraudon, bajo los cañones occidentales, y es allí donde los centauros sitúan el origen de su raza.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Feralas",
		short = "Feralas se alza extraña entre sus vecinas: una selva de árboles antiguos allí donde los páramos que la rodean solo prometen polvo.",
		full = "Feralas se alza extraña entre sus vecinas: una selva de árboles antiguos allí donde los páramos que la rodean solo prometen polvo. Dispersas entre su verdor se alzan las ruinas de los elfos, medio engullidas por raíces y enredaderas, y la mayor de todas es la ciudad sepultada de La Masacre.\n\nAhora los ogros Gordunni dominan Feralas, y la han hecho suya destrozándola. Han arrasado extensiones enteras de bosque, y su corrupción se ha asentado sobre la tierra como una enfermedad. Más allá de los muros de La Masacre, sus partidas de saqueo queman aldeas y asesinan a los viajeros en los bosques del sur, una corrupción que se extiende por las tierras salvajes y cuyo origen se remonta a las ruinas de abajo.\n\nLos tauren Tótem Siniestro aún viven dispersos por la región, perseguidos por quienes recuerdan lo que ha hecho la tribu.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Marjal Revolcafango",
		short = "Aquí los mosquitos nunca descansan, y tampoco el lodo.",
		full = "Aquí los mosquitos nunca descansan, y tampoco el lodo. Los árboles entrelazan sus frondas tan densamente sobre el agua que la luz del sol llega entrecortada, y los crocoliscos y los múrlocs acechan en las aguas salobres y poco profundas donde el mar se une al pantano. En el sur, los dragones negros se reúnen en tal número que la gente llama a ese lugar simplemente la Ciénaga de Fuego.\n\nJaina Valiente fundó el primer verdadero hogar en esta tierra salvaje, al conducir a su pueblo hasta aquí tras la batalla del Monte Hyjal para fundar Theramore en su isla rocosa. Las murallas de su ciudad relucen, pero también la encierran: más allá de los puestos de control dispersos en el camino a Los Baldíos, el pantano sigue tan salvaje como siempre, y su guarnición ha menguado por deserciones silenciosas que nadie sabe explicar.\n\nTambién fue aquí donde la paz entre la Horda y la Alianza se rompió para siempre. El almirante Daelin Valiente trajo la flota de Kul Tiras contra la Horda en el pantano, y la escaramuza que siguió terminó con su muerte, convirtiendo la tregua en abierta enemistad.\n\nEl Poblado Murohelecho se alza donde los ogros Quebrantarrocas abrieron sus puertas a la Horda. Más allá, el camino a Los Baldíos está vacío y cayendo en el abandono, vigilado solo por los raptores y las arañas que siempre han sido los dueños de estas tierras.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "La arena llena el lugar donde antes había una selva. Antes de que el mundo se quebrara, Tanaris era verde y el Imperio Gurubashi la reclamaba como su territorio.",
		full = "La arena llena el lugar donde antes había una selva. Antes de que el mundo se quebrara, Tanaris era verde y el Imperio Gurubashi la reclamaba como su territorio. Cuando el Gran Cataclismo desgarró la tierra, la selva murió y lo que quedó se secó hasta convertirse en dunas y piedra. Una tribu de trols quedó varada aquí cuando las aguas se retiraron, y durante los largos años que siguieron, sus cuerpos y sus costumbres se adaptaron al desierto hasta que dejaron de ser los trols que habían sido y se convirtieron en trols de arena, los Furiarena, un pueblo forjado por la tierra que los atrapó.\n\nLos goblins del Cártel Bonvapor eligieron este páramo para su comercio y fundaron Gadgetzan y Puerto Bonvapor, porque el desierto es lo más parecido a su patria hundida que Kalimdor les permite habitar. Los muelles de Bonvapor se extienden hacia las islas lejanas, pero los goblins guardan sus barcos para sí mismos y no están dispuestos a llevar a ninguna otra raza al otro lado del agua.\n\nBajo las dunas y las montañas del sur, los túneles se extienden por kilómetros, en gran parte sin cartografiar, y quienes bajan no siempre regresan para contar lo que encontraron.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "El otoño lleva diez mil años reinando en Azshara, con sus árboles ardiendo en tonos naranja y rojo sobre acantilados que caen hacia los corales donde todavía yace una ciudad.",
		full = "El otoño lleva diez mil años reinando en Azshara, con sus árboles ardiendo en tonos naranja y rojo sobre acantilados que caen hacia los corales donde todavía yace una ciudad. Azshara fue en otro tiempo la mayor metrópolis que los elfos de la noche llegaron a construir, y cuando llegó la Guerra de los Ancestros, la mayor parte se hundió en el mar. Algunos edificios destrozados aún se aferran al acantilado, contemplando sus propias ruinas bajo el agua.\n\nMucho tiempo después, cuando Illidan Tempestira huyó hacia el norte desde el Monte Hyjal con sus nagas, seguido de mur'guls y sátiros, arrasó la costa de Azshara y destruyó los puertos de los elfos de la noche para que nadie pudiera seguirlo hasta la Tumba de Sargeras. Maiev Cantosombrío y sus Celadoras fueron tras él, acabando con las criaturas enloquecidas que dejaba a su paso.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Frondavil",
		short = "Los árboles de Frondavil no crecen, sino que se pudren. Su corteza supura un icor enfermizo, sus hojas cuelgan negras y enroscadas, y la fauna que vive bajo ellos está retorcida y hambrienta por la corrupción del suelo.",
		full = "Los árboles de Frondavil no crecen, sino que se pudren. Su corteza supura un icor enfermizo, sus hojas cuelgan negras y enroscadas, y la fauna que vive bajo ellos está retorcida y hambrienta por la corrupción del suelo.\n\nLa podredumbre no fue un accidente de la naturaleza. Mientras la Legión Ardiente avanzaba hacia el Monte Hyjal, Archimonde ordenó destruir el bosque para debilitar a los elfos de la noche que custodiaban la montaña, y el señor del terror Tichondrius cumplió esa orden con una reliquia de brujo de un poder terrible, la Calavera de Gul'dan. La tierra respondió muriendo de adentro hacia afuera: los ancestros se volvieron podridos y violentos, las bestias mutaron y la propia tierra quedó envenenada.\n\nFue aquí donde Illidan Tempestira tomó la decisión que marcaría el resto de su vida. Al saber que la calavera podía volverse contra la misma corrupción que había causado, Illidan entró solo en Frondavil, abatió a Tichondrius y reclamó la reliquia para sí. No la entregó después. Su hambre de magia resultó más fuerte que la prudencia, y por usar el propio poder de la Legión fue desterrado por su propio hermano, Malfurion.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Cráter de Un'Goro",
		short = "El Cráter de Un'Goro se encuentra aislado entre tres desiertos, una herida verde hundida en el sur de Kalimdor, donde el mundo olvida ser árido.",
		full = "El Cráter de Un'Goro se encuentra aislado entre tres desiertos, una herida verde hundida en el sur de Kalimdor, donde el mundo olvida ser árido. Dinosaurios más antiguos que la memoria recorren su selva, algunos con tamaños que ningún ser vivo debería alcanzar, y elementales de tierra y fuego caminan tranquilos entre ellos. En las crestas de arriba se alzan pilones que nadie ha sabido explicar jamás.\n\nDurante la guerra del Mar de Dunas, los elfos de la noche se vieron obligados a retroceder a través de este cráter hasta el borde del desierto de Tanaris, y allí se quebró el avance qiraji. Algo en el propio Un'Goro no permitió que los invasores tomaran la tierra, aunque nadie ha dicho qué fue.\n\nUna expedición dirigida por Williden y Hol'anyee Marshal intentó en una ocasión establecerse aquí, pero la ferocidad del cráter resultó ser más de lo que habían previsto. Sus campamentos fueron arrasados, y los supervivientes huyeron a terrenos más altos, donde resistieron en lo que hoy se conoce como el Refugio de Marshal.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Claro de la Luna",
		short = "El Claro de la Luna descansa acunado en un anillo de montañas, un valle oculto donde el bosque nunca ha conocido la corrupción.",
		full = "El Claro de la Luna descansa acunado en un anillo de montañas, un valle oculto donde el bosque nunca ha conocido la corrupción. En su corazón se encuentra el Lago Elune'ara, que lleva el nombre de la propia diosa, y en el pueblo de Amparo de la Noche, a su orilla, tauren y elfos de la noche conviven sin disputas, unidos por una reverencia compartida hacia la naturaleza que los Celadores del Claro de la Luna no permitirán que se rompa.\n\nFue a este valle adonde llegó Malfurion Tempestira en los días de la Guerra de los Ancestros, cuando los elfos de la noche estaban al borde de la ruina frente a la Legión. Malfurion sabía que su pueblo no podría vencer solo, y condujo a Tyrande Susurravientos y a su hermano Illidan hasta la quietud sagrada del Claro de la Luna para suplicar ayuda a Cenarius. El semidiós respondió, y después de que el Gran Cataclismo transformara el mundo, los guardianes de la arboleda y las dríades que se habían refugiado aquí salieron a recorrerlo. El propio Cenarius nunca se marchó, y el Claro de la Luna se convirtió en el lugar más sagrado del culto druídico.\n\nBajo sus innumerables túmulos duermen los santuarios de los druidas del pasado, y bajo las aguas del Elune'ara duerme el semidiós Omen, antaño amado por Elune, con un sueño inquieto.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "Este desierto se encuentra en el extremo suroeste de Kalimdor, un páramo de roca quebrada y arena al que se llega por el amplio camino que sale de Un'Goro.",
		full = "Este desierto se encuentra en el extremo suroeste de Kalimdor, un páramo de roca quebrada y arena al que se llega por el amplio camino que sale de Un'Goro. Bajo su superficie yacen los restos del imperio aqiri, Ahn'Qiraj, cuyo templo central los elfos de la noche sellaron en un intento por impedir que algo terrible despertara. Las ruinas dispersas por Silithus y las colmenas de silítidos que ahora acribillan la arena son prueba suficiente de que el sello no resistió.\n\nHace mucho tiempo, los propios qiraji fueron obligados a replegarse tras el Muro del Escarabajo, donde quedaron aprisionados tras la guerra del Mar de Dunas. Sus sirvientes, los silítidos, quedaron libres, y a lo largo de los siglos se multiplicaron y se extendieron por todo el sur de Kalimdor, hasta que los elfos de la noche juzgaron que la amenaza era demasiado grande para seguir solo vigilándola, y optaron por reabrir la Puerta de Ahn'Qiraj para terminar lo que el Muro solo había retrasado.\n\nEl Círculo Cenarion vigila desde el Fuerte Cenarion, rastreando los enjambres de silítidos y evaluando si representan un peligro demasiado grande para que un solo pueblo lo enfrente por su cuenta.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Cuna del Invierno",
		short = "La nieve se extiende intacta por Cuna del Invierno, y su belleza permanece inalterada incluso donde los demonios han invadido las regiones del sur. Antaño fue el hogar de muchos miembros del Vuelo Azul, entre ellos Haleh, consorte de Malygos.",
		full = "La nieve se extiende intacta por Cuna del Invierno, y su belleza permanece inalterada incluso donde los demonios han invadido las regiones del sur. Antaño fue el hogar de muchos miembros del Vuelo Azul, entre ellos Haleh, consorte de Malygos.\n\nHace diez mil años, los Altonato levantaron aquí la ciudad de Kel'Theril, tras robar el cristal de Zin-Malor de un templo de Eldarath. No pudieron resistirse a poner a prueba su poder, y cuando se hizo añicos, la maldición que desató los devoró. El Gran Cataclismo terminó lo que el cristal había empezado, y Kel'Theril quedó en ruinas. Sus muertos nunca se marcharon. Más tarde, altos elfos llegaron desde Quel'Thalas en busca de los fragmentos del cristal, y la misma locura se apoderó de ellos. Ahora sus fantasmas recorren las ruinas junto a aquellos a quienes vinieron a estudiar.\n\nLos goblins ocupan Vista Eterna en el corazón del valle, y los elfos de la noche aún mantienen aquí su propia vigilancia, custodiando una patria más antigua que ambos pueblos.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Ciudad de Ventormenta",
		short = "Ventormenta se alzó en piedra blanca después de que la Horda orca la incendiara, reconstruida por la Hermandad de los Albañiles bajo el joven rey Varian.",
		full = "Ventormenta se alzó en piedra blanca después de que la Horda orca la incendiara, reconstruida por la Hermandad de los Albañiles bajo el joven rey Varian. Pero cuando las arcas de la corona se vaciaron por las deudas de guerra y la nobleza negó al gremio su salario, la protesta del maestro del gremio Edwin VanCleef fue respondida con la disolución del gremio. Siguieron los disturbios, y en el caos murió la reina Tiffin Wrynn. La ira de Varian empujó a los albañiles al exilio en los Páramos de Poniente, donde se convirtieron en la Hermandad Defias, mientras tras el trono una consejera llamada Katrana Prestor enfrentaba en silencio al rey con el gremio para sus propios fines.\n\nDesde entonces, el rey Varian ha desaparecido en circunstancias sospechosas y, a instancias de Lady Prestor, la corona pasó a su joven hijo, el príncipe Anduin, para preservar el orden en el reino. El alto señor Bolvar Fordragón ejerce como regente de Ventormenta y comandante de sus fuerzas, mientras Lady Prestor lo aconseja sobre el uso de los recursos del reino, sin que nadie sospeche de ella ni la cuestione dentro del castillo.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Orgrimmar se alzó en los años posteriores al Monte Hyjal, cuando el Jefe de Guerra Thrall condujo a su pueblo hasta una costa desolada de Kalimdor.",
		full = "Orgrimmar se alzó en los años posteriores al Monte Hyjal, cuando el Jefe de Guerra Thrall condujo a su pueblo hasta una costa desolada de Kalimdor. Llamó a esta tierra Durotar en honor a su padre, y a la ciudad que levantó allí la llamó Orgrimmar, en honor a Orgrim Martillo Maldito, el amigo y mentor que lo había formado. Se construyó con rapidez, pero no a la ligera: murallas robustas, puertas enormes, torres altas, y las montañas a su espalda talladas para formar parte de la propia fortaleza, de modo que la tierra misma montara guardia sobre la ciudad.\n\nLa Horda que la construyó no era la Horda que una vez había arrasado el mundo. Rota la maldición demoníaca, el pueblo de Thrall pasó de la conquista a la supervivencia, y Orgrimmar fue levantada tanto por otros como por orcos: goblins, tauren y trols Lanza Negra trabajaron junto a ellos, y el mok'nathal Rexxar también echó una mano en la obra. Centauros, arpías, truenagartos, kóbolds y jabaespines pusieron a prueba a la joven ciudad en sus primeros años, pero resistió y se convirtió en hogar no solo de orcos, sino también de trols, tauren y, con el tiempo, de los Renegados, recién acogidos en la Horda.\n\nNi siquiera el viento es un aliado aquí: los vientos cortantes barren los valles con fuerza suficiente para arrancar los techos de los edificios construidos sin cuidado.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Forjaz",
		short = "Forjaz es la capital de los enanos, excavada en las profundidades de la Montaña de Forjaz, en el norte de Dun Morogh, hogar ancestral de los enanos y una de las ciudades más antiguas de Azeroth.",
		full = "Forjaz es la capital de los enanos, excavada en las profundidades de la Montaña de Forjaz, en el norte de Dun Morogh, hogar ancestral de los enanos y una de las ciudades más antiguas de Azeroth. Es la capital de Khaz Modan, gobernada por el rey Magni Barbabronce, del clan Barbabronce.\n\nVasta ciudad subterránea de artesanos, exploradores, mineros y guerreros, famosa por su industria y como centro comercial de la Alianza, Forjaz es a partes iguales fortaleza y capital, un testimonio de la fuerza y la resistencia de los enanos. La ciudad está formada por anillos concéntricos, con niveles más pequeños a mayor profundidad, todos irradiando desde La Gran Fundición, que le da nombre, situada en su centro. Está llena de pequeños pasadizos, tiendas excavadas en las paredes de roca y salas cavernosas. El ambiente es bullicioso, alborotado e industrial, pero acogedor; el fuego ruge en los hogares de las posadas y las tiendas, y se oyen muchas risas y juergas enanas. A diferencia de Ventormenta y Darnassus, la ciudad es una enorme caverna excavada en la tierra por los propios enanos; tanto el techo como el suelo son de piedra dura.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Cima del Trueno",
		short = "Cima del Trueno se alza sobre cuatro mesetas azotadas por el viento por encima de las praderas de Mulgore, y solo se llega a ella por elevadores de cuerda y madera de fabricación tauren, o por largos puentes tendidos entre las alturas.",
		full = "Cima del Trueno se alza sobre cuatro mesetas azotadas por el viento por encima de las praderas de Mulgore, y solo se llega a ella por elevadores de cuerda y madera de fabricación tauren, o por largos puentes tendidos entre las alturas. Tiendas, casas comunales y tótems pintados coronan cada cumbre. Durante generaciones, los tauren vagaron como pueblo nómada, acosados sin descanso por los centauros que recorrían Kalimdor. Fue Cairne Pezuña de Sangre, jefe de la tribu Pezuña de Sangre, quien puso fin a ese exilio. Cuando el Jefe de Guerra Thrall y su Nueva Horda llegaron a Mulgore durante la Tercera Guerra, su fuerza se unió a la de Cairne y juntos derrotaron a los centauros y ganaron por fin las praderas para los tauren. Sobre las mesetas, Cairne levantó un refugio abierto a todas las tribus dispersas, y con el tiempo esas tribus se sometieron a su mando como un solo pueblo, discrepando a veces sobre el camino a seguir, pero nunca sobre la sabiduría de su guía.\n\nLos riscos aún cargan con el peso de aquella fundación en sus alturas y sus puentes, en las tiendas de las tribus reunidas bajo el techo de un mismo jefe.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "Los elfos de la noche construyeron Darnassus después de la Tercera Guerra, cuando su larga inmortalidad les falló. Muchos no pudieron soportar el peso repentino del envejecimiento y la fragilidad.",
		full = "Los elfos de la noche construyeron Darnassus después de la Tercera Guerra, cuando su larga inmortalidad les falló. Muchos no pudieron soportar el peso repentino del envejecimiento y la fragilidad. Varios druidas afligidos decidieron plantar un nuevo Árbol del Mundo para restaurar su vínculo con el mundo eterno. Con Malfurion Tempestira desaparecido, Fandral Corzocelada asumió el manto de archidruida y dirigió la empresa. El árbol que alzaron, Teldrassil, creció frente a la costa hasta que su copa atravesó las nubes, y entre sus ramas los elfos de la noche fundaron su ciudad como testimonio de la supervivencia de su pueblo.\n\nDarnassus está abierta al cielo, a diferencia de las ciudades cerradas y amuralladas de los humanos y los enanos. Está construida alrededor de un amplio lago, cuyas orillas se unen mediante elegantes puentes, y sus senderos están alfombrados de hojas caídas. El Templo de la Luna se alza sobre los árboles como sede de la suma sacerdotisa Tyrande Susurravientos y sus Hermanas de Elune, junto al Salón de la Justicia, rodeado de columnas, donde las centinelas montan guardia. La ciudad sigue siendo aquello para lo que fue construida: un refugio tranquilo y un monumento a un pueblo que aprende a vivir con la mortalidad.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Entrañas",
		short = "Mucho antes de que los Renegados la hicieran suya, Entrañas tenía un nombre y un propósito. Muy por debajo del palacio de Lordaeron se extendían las antiguas criptas de sus muertos reales, sus mazmorras y sus alcantarillas.",
		full = "Mucho antes de que los Renegados la hicieran suya, Entrañas tenía un nombre y un propósito. Muy por debajo del palacio de Lordaeron se extendían las antiguas criptas de sus muertos reales, sus mazmorras y sus alcantarillas. Estaba destinada solo a prisioneros y cadáveres, pero los más pobres del pueblo de Lordaeron bajaban de todos modos en masa a la oscuridad, y las batidas de los guardias para desalojarlos nunca daban resultado.\n\nCuando el control del Rey Exánime sobre sus criaturas se debilitó, Sylvanas Brisaveloz se separó de la Plaga junto con los no-muertos que habían conservado la razón y se volvió contra Arthas, el príncipe caído que la había convertido en lo que era. Lo atrajo a una trampa en el reino en ruinas; él escapó con la ayuda de Kel'Thuzad y huyó al norte para convertirse él mismo en el Rey Exánime. Sylvanas y sus seguidores, dueños del campo de batalla, se dieron el nombre de Renegados y reclamaron las criptas bajo la capital destruida, terminando la fortaleza que la Plaga había comenzado.\n\nLo que se alza hoy es un laberinto construido para la defensa: ríos de lodo venenoso corren por cada avenida, y el aire está cargado de vapores que los vivos apenas soportan respirar. Para los Renegados es un refugio en un mundo que aún les da caza.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}

